const fs = require('fs');
const path = require('path');

const traceB64 = '';
const resolveB64 = '';

fs.mkdirSync(path.join(process.cwd(), 'public'), { recursive: true });
fs.writeFileSync(path.join(process.cwd(), 'public/stamp-trace.webp'), Buffer.from(traceB64, 'base64'));
fs.writeFileSync(path.join(process.cwd(), 'public/stamp-resolve.webp'), Buffer.from(resolveB64, 'base64'));
console.log('Restored stamp assets successfully.');
